import{_ as e,o as a,c as r,a3 as l}from"./chunks/framework.DotqndlA.js";const p=JSON.parse('{"title":"协议支持","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/index.md","filePath":"guide/protocols/index.md","lastUpdated":1786981506000}'),i={name:"guide/protocols/index.md"};function d(o,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="协议支持" tabindex="-1">协议支持 <a class="header-anchor" href="#协议支持" aria-label="Permalink to &quot;协议支持&quot;">​</a></h1><p>EMS Simulate 支持 4 大工业通信协议族，每种协议均可配置为<strong>服务端</strong>（模拟设备）或<strong>客户端</strong>（读取真实设备），并提供专属的操作界面与报文查看能力。</p><h2 id="协议概览" tabindex="-1">协议概览 <a class="header-anchor" href="#协议概览" aria-label="Permalink to &quot;协议概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th style="text-align:center;">服务端</th><th style="text-align:center;">客户端</th><th>默认端口</th><th>典型设备</th></tr></thead><tbody><tr><td><a href="./modbus/">Modbus TCP / RTU</a></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>502（TCP）/ 串口（RTU）</td><td>PLC、RTU、传感器</td></tr><tr><td><a href="./iec104/">IEC 60870-5-104</a></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>2404</td><td>测控装置、变电站远动</td></tr><tr><td><a href="./dlt645/">DL/T 645-2007</a></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>8899</td><td>智能电能表</td></tr><tr><td><a href="./iec61850/">IEC 61850</a></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>102（MMS）</td><td>智能变电站 IED</td></tr></tbody></table><blockquote><p><strong>角色说明</strong></p><ul><li><strong>服务端</strong>：软件模拟真实设备，响应上位机的请求（如响应主站轮询、处理总召唤、应答抄表等）；</li><li><strong>客户端</strong>：软件作为上位机主动读取真实设备（用于测试真实设备或验证服务端模拟的正确性）。</li></ul></blockquote><h2 id="各协议文档入口" tabindex="-1">各协议文档入口 <a class="header-anchor" href="#各协议文档入口" aria-label="Permalink to &quot;各协议文档入口&quot;">​</a></h2><h3 id="modbus-tcp-rtu" tabindex="-1"><a href="./modbus/">Modbus TCP / RTU</a> <a class="header-anchor" href="#modbus-tcp-rtu" aria-label="Permalink to &quot;[Modbus TCP / RTU](./modbus/)&quot;">​</a></h3><p>工业自动化领域应用最广泛的通信协议，支持 TCP 网络与 RTU 串口两种模式。</p><ul><li><a href="./modbus/">协议介绍</a> · <a href="./modbus/operation.html">操作指南</a> · <a href="./modbus/packet-view.html">报文查看</a></li></ul><h3 id="iec-60870-5-104" tabindex="-1"><a href="./iec104/">IEC 60870-5-104</a> <a class="header-anchor" href="#iec-60870-5-104" aria-label="Permalink to &quot;[IEC 60870-5-104](./iec104/)&quot;">​</a></h3><p>电力系统远动通信标准协议，广泛用于变电站与调度中心之间的数据传输。</p><ul><li><a href="./iec104/">协议介绍</a> · <a href="./iec104/operation.html">操作指南</a> · <a href="./iec104/packet-view.html">报文查看</a></li></ul><h3 id="dl-t-645-2007" tabindex="-1"><a href="./dlt645/">DL/T 645-2007</a> <a class="header-anchor" href="#dl-t-645-2007" aria-label="Permalink to &quot;[DL/T 645-2007](./dlt645/)&quot;">​</a></h3><p>中国电力行业多功能电能表通信协议标准，用于电表数据采集。</p><ul><li><a href="./dlt645/">协议介绍</a> · <a href="./dlt645/operation.html">操作指南</a> · <a href="./dlt645/packet-view.html">报文查看</a></li></ul><h3 id="iec-61850" tabindex="-1"><a href="./iec61850/">IEC 61850</a> <a class="header-anchor" href="#iec-61850" aria-label="Permalink to &quot;[IEC 61850](./iec61850/)&quot;">​</a></h3><p>新一代智能变电站通信标准，提供 MMS / GOOSE / Reports / Files / SCL 完整功能链。</p><ul><li><a href="./iec61850/">协议介绍</a> · <a href="./iec61850/operation.html">操作指南</a> · <a href="./iec61850/packet-view.html">报文查看</a></li></ul><h2 id="通用能力" tabindex="-1">通用能力 <a class="header-anchor" href="#通用能力" aria-label="Permalink to &quot;通用能力&quot;">​</a></h2><p>无论使用哪种协议，EMS Simulate 都提供以下通用能力：</p><ul><li><strong>报文查看</strong>：实时捕获并解析各协议通讯报文，支持报文详情与原始字节定位；</li><li><strong>测点体系</strong>：统一的 YC（遥测）/ YX（遥信）/ YK（遥控）/ YT（遥调）测点类型；</li><li><strong>数据模拟</strong>：随机、自增、自减、计划、正弦波、斜坡、脉冲 7 种模拟方式；</li><li><strong>测点映射</strong>：跨设备测点联动与公式计算。</li></ul><p>相关通用操作见 <a href="./../device/device-management.html">设备管理</a> 与 <a href="./../point/point-types.html">测点模块</a>。</p>',22)])])}const m=e(i,[["render",d]]);export{p as __pageData,m as default};
